with
cols as (select 'col '||table_schema||'.'||table_name||'.'||column_name||' '||data_type||coalesce('('||udt_name||')','')||' null='||is_nullable||' def='||coalesce(column_default,'') x from information_schema.columns where table_schema in ('public')),
cons as (select 'con '||n.nspname||'.'||cl.relname||'.'||c.conname||' '||pg_get_constraintdef(c.oid) x from pg_constraint c join pg_class cl on cl.oid=c.conrelid join pg_namespace n on n.oid=cl.relnamespace where n.nspname='public'),
idx as (select 'idx '||schemaname||'.'||indexname||' '||indexdef x from pg_indexes where schemaname='public'),
pol as (select 'pol '||schemaname||'.'||tablename||'.'||policyname||' '||permissive||' '||array_to_string(roles,',')||' '||cmd||' q='||coalesce(qual,'')||' c='||coalesce(with_check,'') x from pg_policies where schemaname in ('public','storage')),
rls as (select 'rls '||n.nspname||'.'||c.relname||' '||c.relrowsecurity||' force='||c.relforcerowsecurity x from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')),
fn as (select 'fn '||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||') ret='||pg_get_function_result(p.oid)||' secdef='||p.prosecdef||' cfg='||coalesce(array_to_string(p.proconfig,','),'')||' src='||md5(regexp_replace(p.prosrc,'\s+','','g')) x from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
trg as (select 'trg '||pg_get_triggerdef(t.oid) x from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','auth','storage')),
vw as (select 'view '||schemaname||'.'||viewname||' '||md5(regexp_replace(definition,'\s+','','g')) x from pg_views where schemaname='public'),
tgr as (select 'grant '||table_schema||'.'||table_name||' '||grantee||' '||string_agg(privilege_type,',' order by privilege_type) x from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','service_role','supabase_auth_admin') group by table_schema,table_name,grantee),
fgr as (select 'fgrant '||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||') '||coalesce(array_to_string(array(select (aclexplode(p.proacl)).grantee::regrole::text||':'||(aclexplode(p.proacl)).privilege_type order by 1),','),'default') x from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
typ as (select 'enum '||t.typname||' '||string_agg(e.enumlabel,',' order by e.enumsortorder) x from pg_type t join pg_enum e on e.enumtypid=t.oid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' group by t.typname),
seq as (select 'seq '||sequence_schema||'.'||sequence_name x from information_schema.sequences where sequence_schema='public'),
ext as (select 'ext '||extname x from pg_extension),
cronj as (select 'cron '||jobname||' '||schedule||' '||md5(regexp_replace(command,'\s+','','g')) x from cron.job)
select x from (select x from cols union all select x from cons union all select x from idx union all select x from pol union all select x from rls union all select x from fn union all select x from trg union all select x from vw union all select x from tgr union all select x from fgr union all select x from typ union all select x from seq union all select x from ext union all select x from cronj) a order by x
